
// Load the asset manifest generated by .NET during publish.
self.importScripts("./service-worker-assets.js");

const cacheNamePrefix = "lifedeck-offline-";
const cacheName =
    `${cacheNamePrefix}${self.assetsManifest.version}`;

const offlineAssetsInclude = [
    /\.(dll|pdb|wasm|html|js|mjs|json|css|woff2?|ttf|png|jpe?g|gif|ico|svg|webmanifest|blat|dat)$/i
];

const offlineAssetsExclude = [
    /(^|\/)service-worker\.js$/i,
    /(^|\/)service-worker-assets\.js$/i
];

self.addEventListener("install", event => {
    event.waitUntil(installOfflineCache());
});

self.addEventListener("activate", event => {
    event.waitUntil(cleanOldCaches());
});

self.addEventListener("fetch", event => {
    if (event.request.method !== "GET") {
        return;
    }

    // External APIs remain network-only.
    if (!event.request.url.startsWith(self.registration.scope)) {
        return;
    }

    event.respondWith(handleFetch(event.request));
});

async function installOfflineCache() {
    const assets = self.assetsManifest.assets
        .filter(asset =>
            offlineAssetsInclude.some(pattern =>
                pattern.test(asset.url)))
        .filter(asset =>
            !offlineAssetsExclude.some(pattern =>
                pattern.test(asset.url)));

    const requests = assets.map(asset =>
        new Request(
            new URL(asset.url, self.registration.scope),
            {
                integrity: asset.hash,
                cache: "no-cache"
            }
        )
    );

    const cache = await caches.open(cacheName);

    // A failed installation must not activate an incomplete cache.
    await cache.addAll(requests);

    console.info("LifeDeck offline cache installed.");
}

async function cleanOldCaches() {
    const keys = await caches.keys();

    await Promise.all(
        keys
            .filter(key =>
                key.startsWith(cacheNamePrefix) &&
                key !== cacheName)
            .map(key => caches.delete(key))
    );

    console.info("LifeDeck offline cache activated.");
}

async function handleFetch(request) {
    const cache = await caches.open(cacheName);
    const url = new URL(request.url);

    // Blazor routes all use the same index.html entry point.
    const isPageNavigation =
        request.mode === "navigate" &&
        !/\.[a-z0-9]+$/i.test(url.pathname);

    const lookupRequest = isPageNavigation
        ? new URL("index.html", self.registration.scope).href
        : request;

    const cachedResponse =
        await cache.match(lookupRequest);

    if (cachedResponse) {
        return cachedResponse;
    }

    return fetch(request);
}
